import csv, os, json, math
from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions/solution.csv"
GAP = 0.0005

def read_csv(name):
    with open(os.path.join(DATA, name)) as f:
        return list(csv.DictReader(f))

days = read_csv("days.csv")
shifts = read_csv("shifts.csv")
skills = read_csv("skills.csv")
contracts = read_csv("contracts.csv")
nurses = read_csv("nurses.csv")
nurse_skills = read_csv("nurse_skills.csv")
coverage = read_csv("coverage_requirements.csv")
preassignments = read_csv("preassignments.csv")
incompat = read_csv("incompatibilities.csv")
charge_rules = read_csv("charge_coverage_rules.csv")
fairness_rules = read_csv("fairness_rules.csv")
period_rules = read_csv("period_consecutiveness_rules.csv")
contract_rest = read_csv("contract_rest_rules.csv")
contract_dayoff = read_csv("contract_dayoff_rules.csv")
config = json.load(open(os.path.join(DATA, "config.json")))
weights = config["objective_weights"]

day_list = [d["day"] for d in days]
day_idx = {d["day"]: i for i, d in enumerate(days)}
day_weekday = {d["day"]: d["weekday"] for d in days}
day_is_weekend = {d["day"]: int(d["is_weekend"]) for d in days}
day_is_sunday = {d["day"]: int(d["is_sunday"]) for d in days}
day_is_holiday = {d["day"]: int(d["is_holiday"]) for d in days}
day_weekend_id = {d["day"]: d["weekend_id"] for d in days}

shift_list = [s["shift_id"] for s in shifts]
shift_period = {s["shift_id"]: s["period"] for s in shifts}
shift_start = {s["shift_id"]: int(s["start_minute"]) for s in shifts}
shift_dur = {s["shift_id"]: int(s["duration_minutes"]) for s in shifts}
shift_night = {s["shift_id"]: int(s["is_night"]) for s in shifts}

contract_map = {c["contract_id"]: c for c in contracts}
nurse_contract = {n["nurse_id"]: n["contract_id"] for n in nurses}
nurse_list = [n["nurse_id"] for n in nurses]

# Eligible tuples
elig = set()
standard = set()
for row in nurse_skills:
    n, sk, s, std = row["nurse_id"], row["skill_id"], row["shift_id"], int(row["standard"])
    elig.add((n, sk, s))
    if std:
        standard.add((n, sk, s))

# Preassignments (all hard fixed A)
fixed_A = set()
for row in preassignments:
    if row["hard"] == "1" and row["assignment_type"] == "fixed_status" and row["shift_id"] == "A":
        fixed_A.add((row["nurse_id"], row["day"]))

# Build model
model = Model("nurse_rostering")
model.setMinimize()
model.setRealParam("limits/gap", GAP)
tl = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if tl:
    model.setRealParam("limits/time", float(tl))
else:
    model.setRealParam("limits/time", 300.0)

# Variables
x = {}  # (n,d,s,sk)
a = {}  # (n,d)
ss = {} # (n,d)
for n in nurse_list:
    for d in day_list:
        a[(n,d)] = model.addVar(vtype="B", name=f"a_{n}_{d}", obj=0)
        ss[(n,d)] = model.addVar(vtype="B", name=f"s_{n}_{d}", obj=0)
        for (nn, sk, s) in elig:
            if nn == n:
                x[(n,d,s,sk)] = model.addVar(vtype="B", name=f"x_{n}_{d}_{s}_{sk}", obj=0)

# At most one state
for n in nurse_list:
    for d in day_list:
        expr = a[(n,d)] + ss[(n,d)]
        for (nn, sk, s) in elig:
            if nn == n:
                expr += x[(n,d,s,sk)]
        model.addCons(expr <= 1, name=f"one_{n}_{d}")

# Fixed A
for (n,d) in fixed_A:
    model.fixVar(a[(n,d)], 1)
    for (nn, sk, s) in elig:
        if nn == n:
            model.fixVar(x[(n,d,s,sk)], 0)
    model.fixVar(ss[(n,d)], 0)

# Contract working weekdays
working_wd = {}
for c in contracts:
    working_wd[c["contract_id"]] = set(c["working_weekdays"].split(";"))

def is_counted(n, d):
    wd = day_weekday[d]
    return wd in working_wd[nurse_contract[n]]

# Counted assignment variables (for contract rules)
# counted[n,d] = sum x + (a+ss if working weekday)
counted = {}
for n in nurse_list:
    for d in day_list:
        if is_counted(n, d):
            expr = quicksum(x[(n,d,s,sk)] for (nn,sk,s) in elig if nn==n) + a[(n,d)] + ss[(n,d)]
        else:
            expr = quicksum(x[(n,d,s,sk)] for (nn,sk,s) in elig if nn==n)
        counted[(n,d)] = expr

# Contract assignment bounds
for n in nurse_list:
    c = contract_map[nurse_contract[n]]
    total = quicksum(counted[(n,d)] for d in day_list)
    model.addCons(total >= int(c["min_assignments"]), name=f"minasg_{n}")
    model.addCons(total <= int(c["max_assignments"]), name=f"maxasg_{n}")

# Work minutes
for n in nurse_list:
    c = contract_map[nurse_contract[n]]
    avg = int(c["average_work_minutes"])
    expr = 0
    for d in day_list:
        for (nn,sk,s) in elig:
            if nn==n:
                expr += shift_dur[s] * x[(n,d,s,sk)]
        if is_counted(n,d):
            expr += avg * (a[(n,d)] + ss[(n,d)])
    model.addCons(expr >= int(c["min_work_minutes"]), name=f"minwm_{n}")
    model.addCons(expr <= int(c["max_work_minutes"]), name=f"maxwm_{n}")

# Consecutive working days <= 8
max_consec_work = 8
for n in nurse_list:
    for i in range(len(day_list) - max_consec_work + 1):
        ds = day_list[i:i+max_consec_work+1]
        model.addCons(quicksum(counted[(n,d)] for d in ds) <= max_consec_work, name=f"conw_{n}_{i}")

# Consecutive off days <= 6
max_consec_off = 6
for n in nurse_list:
    for i in range(len(day_list) - max_consec_off + 1):
        ds = day_list[i:i+max_consec_off+1]
        model.addCons(quicksum(1 - counted[(n,d)] for d in ds) <= max_consec_off, name=f"conoff_{n}_{i}")

# Rest between consecutive detailed shifts (660 min baseline)
min_rest = 660
for n in nurse_list:
    for i in range(len(day_list)-1):
        d1, d2 = day_list[i], day_list[i+1]
        for (nn,sk1,s1) in elig:
            if nn!=n: continue
            for (nn2,sk2,s2) in elig:
                if nn2!=n: continue
                rest = shift_start[s2] - (shift_start[s1] + shift_dur[s1])
                if rest < min_rest:
                    model.addCons(x[(n,d1,s1,sk1)] + x[(n,d2,s2,sk2)] <= 1, name=f"rest_{n}_{d1}_{s1}_{d2}_{s2}")

# 6-streak dayoff: after 6 consecutive counted, day 7 off
for n in nurse_list:
    for i in range(len(day_list)-7):
        ds6 = day_list[i:i+6]
        d7 = day_list[i+6]
        model.addCons(quicksum(counted[(n,d)] for d in ds6) <= 6 - counted[(n,d7)], name=f"dayoff_{n}_{i}")

# Period run-length: Late <= 2, Day/Early <= 6
for n in nurse_list:
    for period, maxrun in [("Late",2), ("Day",6), ("Early",6)]:
        for i in range(len(day_list)-maxrun):
            ds = day_list[i:i+maxrun+1]
            expr = quicksum(x[(n,d,s,sk)] for d in ds for (nn,sk,s) in elig if nn==n and shift_period[s]==period)
            model.addCons(expr <= maxrun, name=f"run_{n}_{period}_{i}")

# Coverage
cov_min = {}
cov_opt = {}
cov_max = {}
for row in coverage:
    key = (row["day"], row["period"], row["skill_id"])
    cov_min[key] = int(row["min_required"])
    cov_opt[key] = int(row["optimal_required"])
    cov_max[key] = int(row["max_allowed"])

insuf_vars = {}
under_vars = {}
exceed_vars = {}
for key in cov_min:
    d, period, sk = key
    expr = quicksum(x[(n,d,s,sk)] for n in nurse_list for (nn,skk,s) in elig if nn==n and skk==sk and shift_period[s]==period)
    mn = cov_min[key]
    if mn > 0:
        v = model.addVar(vtype="C", lb=0, name=f"insuf_{d}_{period}_{sk}", obj=weights["insufficient_staffing"])
        model.addCons(expr + v >= mn, name=f"insufc_{d}_{period}_{sk}")
        insuf_vars[key] = v
    opt = cov_opt[key]
    if opt > 0:
        v = model.addVar(vtype="C", lb=0, name=f"under_{d}_{period}_{sk}", obj=weights["understaffing"])
        model.addCons(expr + v >= opt, name=f"underc_{d}_{period}_{sk}")
        under_vars[key] = v
    mx = cov_max[key]
    if mx < 999:
        v = model.addVar(vtype="C", lb=0, name=f"exceed_{d}_{period}_{sk}", obj=weights["exceeding_staffing"])
        model.addCons(expr - v <= mx, name=f"exceedc_{d}_{period}_{sk}")
        exceed_vars[key] = v
    else:
        model.addCons(expr <= mx, name=f"covmax_{d}_{period}_{sk}")

# Standard shift penalty
for (n,sk,s) in elig:
    if (n,sk,s) not in standard:
        for d in day_list:
            model.setObjCoeff(x[(n,d,s,sk)], weights["standard_shift"])

# Incompatibilities
for row in incompat:
    na, nb = row["nurse_id_a"], row["nurse_id_b"]
    scope = row["scope"]
    hard = row["hard"] == "1"
    pen = int(row["penalty"])
    sfilter = row["shift_id"]
    if scope == "same_shift":
        for d in day_list:
            for s in shift_list:
                if sfilter and s != sfilter: continue
                expr = 0
                for sk in ["Skill_1","Skill_2","Skill_3"]:
                    if (na,sk,s) in elig: expr += x[(na,d,s,sk)]
                    if (nb,sk,s) in elig: expr += x[(nb,d,s,sk)]
                if hard:
                    model.addCons(expr <= 1, name=f"inc_{na}_{nb}_{d}_{s}")
                else:
                    v = model.addVar(vtype="C", lb=0, name=f"incv_{na}_{nb}_{d}_{s}", obj=pen)
                    model.addCons(expr - 1 <= v, name=f"incvc_{na}_{nb}_{d}_{s}")
    elif scope == "same_day":
        for d in day_list:
            expr_a = quicksum(x[(na,d,s,sk)] for (nn,sk,s) in elig if nn==na)
            expr_b = quicksum(x[(nb,d,s,sk)] for (nn,sk,s) in elig if nn==nb)
            if hard:
                model.addCons(expr_a + expr_b <= 1, name=f"inc_{na}_{nb}_{d}")
            else:
                v = model.addVar(vtype="C", lb=0, name=f"incv_{na}_{nb}_{d}", obj=pen)
                model.addCons(expr_a + expr_b - 1 <= v, name=f"incvc_{na}_{nb}_{d}")

# Charge coverage
for row in charge_rules:
    pen = int(row["penalty"])
    pool = row["nurse_ids"].split(";")
    period = row["period"]
    sk = row["skill_id"]
    day_scope = row["day_scope"]
    for d in day_list:
        if day_scope == "weekend" and not day_is_weekend[d]: continue
        # z = 1 if any Early assignment on day d
        early_expr = quicksum(x[(n,d,s,sk2)] for n in nurse_list for (nn,sk2,s) in elig if nn==n and shift_period[s]==period)
        z = model.addVar(vtype="B", name=f"z_{row['rule_id']}_{d}")
        model.addCons(z <= early_expr, name=f"zc1_{row['rule_id']}_{d}")
        model.addCons(z >= early_expr - 19, name=f"zc2_{row['rule_id']}_{d}")
        charge_expr = quicksum(x[(n,d,s,sk)] for n in pool for (nn,sk2,s) in elig if nn==n and sk2==sk and shift_period[s]==period)
        v = model.addVar(vtype="C", lb=0, name=f"chv_{row['rule_id']}_{d}", obj=pen)
        model.addCons(charge_expr + v >= z, name=f"chvc_{row['rule_id']}_{d}")

# Fairness
for row in fairness_rules:
    pen = int(row["penalty"])
    allowed = int(row["allowed_difference"])
    pool = row["nurse_ids"].split(";")
    metric = row["metric"]
    period = row["period"]
    sk = row["skill_id"]
    day_scope = row["day_scope"]
    ds = [d for d in day_list if (day_scope=="all" or (day_scope=="weekend" and day_is_weekend[d]) or (day_scope=="weekday" and not day_is_weekend[d]))]
    # Compute per-nurse metric
    nurse_vals = {}
    for n in pool:
        if metric == "period_assignments":
            expr = quicksum(x[(n,d,s,sk)] for d in ds for (nn,sk2,s) in elig if nn==n and sk2==sk and shift_period[s]==period)
        else:
            expr = quicksum(counted[(n,d)] for d in ds)
        nurse_vals[n] = expr
    # max-min
    vmax = model.addVar(vtype="C", lb=0, name=f"fvmax_{row['rule_id']}")
    vmin = model.addVar(vtype="C", lb=0, name=f"fvmin_{row['rule_id']}")
    for n in pool:
        model.addCons(vmax >= nurse_vals[n], name=f"fvmx_{row['rule_id']}_{n}")
        model.addCons(vmin <= nurse_vals[n], name=f"fvmn_{row['rule_id']}_{n}")
    v = model.addVar(vtype="C", lb=0, name=f"fv_{row['rule_id']}", obj=pen)
    model.addCons(vmax - vmin - allowed <= v, name=f"fv_c_{row['rule_id']}")

model.optimize()

# Write solution
rows = []
for n in nurse_list:
    for d in day_list:
        if model.getVal(a[(n,d)]) > 0.5:
            rows.append([n, d, "A", ""])
        if model.getVal(ss[(n,d)]) > 0.5:
            rows.append([n, d, "S", ""])
        for (nn,sk,s) in elig:
            if nn==n and model.getVal(x[(n,d,s,sk)]) > 0.5:
                rows.append([n, d, s, sk])

rows.sort(key=lambda r: (r[1], r[0]))
os.makedirs("/app/submissions", exist_ok=True)
with open(OUT, "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["nurse_id","day","shift_id","skill_id"])
    w.writerows(rows)

print(f"Status: {model.getStatus()}")
print(f"Objective: {model.getObjval():.8f}")
print(f"Rows written: {len(rows)}")
